func (t UpdatedType) ValueFromObject(ctx context.Context, in basetypes.ObjectValue) (basetypes.ObjectValuable, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributes := in.Attributes()

	timeAttribute, ok := attributes["time"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`time is missing from object`)

		return nil, diags
	}

	timeVal, ok := timeAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`time expected to be basetypes.StringValue, was: %T`, timeAttribute))
	}

	usernameAttribute, ok := attributes["username"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`username is missing from object`)

		return nil, diags
	}

	usernameVal, ok := usernameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`username expected to be basetypes.StringValue, was: %T`, usernameAttribute))
	}

	if diags.HasError() {
		return nil, diags
	}

	return UpdatedValue{
		Time:     timeVal,
		Username: usernameVal,
		state:    attr.ValueStateKnown,
	}, diags
}

func NewUpdatedValueNull() UpdatedValue {
	return UpdatedValue{
		state: attr.ValueStateNull,
	}
}

func NewUpdatedValueUnknown() UpdatedValue {
	return UpdatedValue{
		state: attr.ValueStateUnknown,
	}
}

func NewUpdatedValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (UpdatedValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing UpdatedValue Attribute Value",
				"While creating a UpdatedValue value, a missing attribute value was detected. "+
					"A UpdatedValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("UpdatedValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid UpdatedValue Attribute Type",
				"While creating a UpdatedValue value, an invalid attribute value was detected. "+
					"A UpdatedValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("UpdatedValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("UpdatedValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra UpdatedValue Attribute Value",
				"While creating a UpdatedValue value, an extra attribute value was detected. "+
					"A UpdatedValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra UpdatedValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewUpdatedValueUnknown(), diags
	}

	timeAttribute, ok := attributes["time"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`time is missing from object`)

		return NewUpdatedValueUnknown(), diags
	}

	timeVal, ok := timeAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`time expected to be basetypes.StringValue, was: %T`, timeAttribute))
	}

	usernameAttribute, ok := attributes["username"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`username is missing from object`)

		return NewUpdatedValueUnknown(), diags
	}

	usernameVal, ok := usernameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`username expected to be basetypes.StringValue, was: %T`, usernameAttribute))
	}

	if diags.HasError() {
		return NewUpdatedValueUnknown(), diags
	}

	return UpdatedValue{
		Time:     timeVal,
		Username: usernameVal,
		state:    attr.ValueStateKnown,
	}, diags
}

func NewUpdatedValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) UpdatedValue {
	object, diags := NewUpdatedValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewUpdatedValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t UpdatedType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewUpdatedValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewUpdatedValueUnknown(), nil
	}

	if in.IsNull() {
		return NewUpdatedValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewUpdatedValueMust(UpdatedValue{}.AttributeTypes(ctx), attributes), nil
}

